parts.text:
Now write the Kotlin files. Let me create the core package.

File 1: `TextCleaner.kt` — the big one.

Careful details:
- `_run_re` = `[A-Za-z]+|[\u0400-\u052F\uA640-\uA69F]+|[^A-Za-z\u0400-\u052F\uA640-\uA69F]+`
- word re = `[A-Za-z\u0400-\u052F\uA640-\uA69F]{2,}`

Let me write it.

```kotlin
package com.screenocr.client.core

object TextCleaner {

    private val LAT_TO_CYR = mapOf(
        'a' to 'а', 'c' to 'с', 'e' to 'е', 'o' to 'о', 'p' to 'р', 'x' to 'х', 'y' to 'у',
        'A' to 'А', 'B' to 'В', 'C' to 'С', 'E' to 'Е', 'H' to 'Н', 'K' to 'К', 'M' to 'М',
        'O' to 'О', 'P' to 'Р', 'T' to 'Т', 'X' to 'Х', 'Y' to 'У', 'U' to 'У', 'u' to 'у',
        'i' to 'і', 'I' to 'І',
    )

    private val CYR_TO_LAT = mapOf(
        'а' to 'a', 'с' to 'c', 'е' to 'e', 'о' to 'o', 'р' to 'p', 'х' to 'x', 'у' to 'y',
        'А' to 'A', 'В' to 'B', 'С' to 'C', 'Е' to 'E', 'Н' to 'H', 'К' to 'K', 'М' to 'M',
        'О' to 'O', 'Р' to 'P', 'Т' to 'T', 'Х' to 'X', 'У' to 'Y',
        'і' to 'i', 'І' to 'I', 'ї' to 'i', 'Ї' to 'I', 'є' to 'e', 'Є' to 'E',
        'ґ' to 'g', 'Ґ' to 'G', 'ё' to 'e', 'Ё' to 'E',
    )

    private val UKR_TO_RUS = mapOf(
        'І' to 'И', 'і' to 'и', 'Ї' to 'Ы', 'ї' to 'ы', 'Є' to 'Е', 'є' to 'е',
    )

    private val CYR_UNIQUE = "абвгдежзийклмнопстуфчшщъыьэюяёЁ"
    private val LAT_UNIQUE = "BbDdFfGgJjLlNnQqRrSsWwZz"

    private val KNOWN_CORRECTIONS = mapOf(
        "curl" to "Ctrl", "ctri" to "Ctrl", "cirl" to "Ctrl",
        "alf" to "Alt", "shifl" to "Shift", "shlft" to "Shift",
        "enler" to "Enter", "esc" to "Esc", "dei" to "Del",
    )

    val KNOWN_WORDS: Set<String> = setOf(...)

    private val RUN_RE = Regex("[A-Za-z]+|[\\u0400-\\u052F\\uA640-\\uA69F]+|[^A-Za-z\\u0400-\\u052F\\uA640-\\uA69F]+")
    private val WORD_RE = Regex("[A-Za-z\\u0400-\\u052F\\uA640-\\uA69F]{2,}")
    ...
}
```

Wait: KNOWN_WORDS has a Chinese word "战争" and "ante". Also "ы" etc.

Note: `_KNOWN_WORDS` contains "ё" chars — fine.

Note "с" appears twice? Doesn't matter, it's a set.

Let me write the whole file carefully.

For `fixLookalikesPerWord`, Python `_fix_word` gets a match; I need `match.value`.

```kotlin
fun fixLookalikesPerWord(text: String): String {
    if (text.isEmpty()) return text
    return WORD_RE.replace(text) { m -> fixWord(m.value) }
}

private fun fixWord(word: String): String {
    val runs = RUN_RE.findAll(word).map { it.value }.toList()
    val letterRuns = runs.filter { isLatRun(it) || isCyrRun(it) }
    if (letterRuns.size >= 2 && letterRuns.zipWithNext().any { (a, b) ->
            a.length >= 2 && b.length >= 2 &&
                ((isCyrRun(a) && isLatRun(b)) || (isLatRun(a) && isCyrRun(b)))
        }) {
        val out = runs.map { r ->
            if (isCyrRun(r) && r.length >= 2) r.map { UKR_TO_RUS[it] ?: it }.joinToString("") else r
        }
        val res = mutableListOf<String>()
        var prevLetters = ""
        for (chunk in out) {
            val boundary = res.isNotEmpty() && chunk.length >= 2 &&
                ((isLatRun(chunk) && isCyrRun(prevLetters) && prevLetters.length >= 2) ||
                 (isCyrRun(chunk) && isLatRun(prevLetters) && prevLetters.length >= 2))
            if (boundary) res.add(" ")
            res.add(chunk)
            if (isLatRun(chunk) || isCyrRun(chunk)) prevLetters = chunk
            else if (chunk.isBlank()) prevLetters = ""
        }
        return res.joinToString("")
    }
    val cyrUnique = word.count { it in CYR_UNIQUE }
    val latUnique = word.count { it in LAT_UNIQUE }
    if (cyrUnique == 0 && latUnique == 0) {
        val cyrAll = word.count { isCyr(it) }
        val latAll = word.count { it in 'a'..'z' || it in 'A'..'Z' }
        if (cyrAll > latAll) {
            val mapped = word.map { LAT_TO_CYR[it] ?: it }.joinToString("")
            return mapped.map { UKR_TO_RUS[it] ?: it }.joinToString("")
        }
        if (latAll > cyrAll) {
            return word.map { CYR_TO_LAT[it] ?: it }.joinToString("")
        }
        return word
    }
    if (cyrUnique > latUnique) {
        val mapped = word.map { LAT_TO_CYR[it] ?: it }.joinToString("")
        return mapped.map { UKR_TO_RUS[it] ?: it }.joinToString("")
    }
    if (latUnique > cyrUnique) {
        return word.map { CYR_TO_LAT[it] ?: it }.joinToString("")
    }
    return word
}
```

Note: `chunk.strip() == ""` → `chunk.isBlank()`. Since chunk is non-letter run, it's punctuation/whitespace.

Careful: Python `_is_lat_run` requires len>=1 and all ASCII letters. Same.

`isCyr(c)`: `c.code in 0x0400..0x052F || c.code in 0xA640..0xA69F`.

Now the rest. `joinLineHyphens`:
```kotlin
private val HYPHEN_RE = Regex("(?U)(\\w)-\\s*\n\\s*(\\w)")
fun joinLineHyphens(text: String): String = HYPHEN_RE.replace(text, "$1$2")
```

`filterGarbageTokens`:
```kotlin
private val CYR_RE = Regex("[а-яА-ЯёЁ]")
private val LAT_RE = Regex("[a-zA-Z]")
private const val WHITELIST = ".,!?;:-'\"()—–…/ \n"
fun filterGarbageTokens(text: String): String {
    if (text.isEmpty()) return text
    val result = mutableListOf<String>()
    for (line in text.split("\n")) {
        val cleaned = splitWhitespace(line).filter { w ->
            CYR_RE.containsMatchIn(w) || LAT_RE.containsMatchIn(w) ||
                w.all { it in WHITELIST || it.isDigit() }
        }
        if (cleaned.isNotEmpty()) result.add(cleaned.joinToString(" "))
    }
    return result.joinToString("\n")
}
private fun splitWhitespace(s: String) = s.split(Regex("\\s+")).filter { it.isNotEmpty() }
```

Hmm: `all {}` on empty string returns true — but tokens are never empty. Fine.

`looksLikeDictionaryRamp`:
```kotlin
private val RAMP_SPLIT_RE = Regex("[\\s,.\\-!?;:\"'()\\[\\]{}<>+/=…—–%№]+")
fun looksLikeDictionaryRamp(text: String): Boolean {
    if (text.length < 10) return false
    for (word in RAMP_SPLIT_RE.split(text)) {
        if (word.length < 8) continue
        var ascending = 1
        for (i in 1 until word.length) {
            if (word[i] > word[i - 1]) {
                ascending++
                if (ascending >= 10) return true
            } else ascending = 1
        }
    }
    return false
}
```

`normalizeWhitespace`:
```kotlin
fun normalizeWhitespace(text: String): String {
    if (text.isEmpty()) return text
    var t = text
    t = Regex("[ \\t]+").replace(t, " ")
    t = Regex(" *\n *").replace(t, "\n")
    t = Regex("\\.{4,}").replace(t, "…")
    t = Regex("\\.\\.\\.").replace(t, "…")
    t = Regex("\\s+([,.!?;:])").replace(t, "$1")
    t = Regex("([(\\[«])\\s+").replace(t, "$1")
    return t.split("\n").joinToString("\n") { it.trim() }
}
```

`normalizeNumbers`:
```kotlin
private val NUMBER_RE = Regex("\\b\\d+[.,]\\d*0+\\b")
fun normalizeNumbers(text: String): String = NUMBER_RE.replace(text) { m ->
    val s = m.value
    val sep = if (',' in s) ',' else '.'
    val i = s.indexOf(sep)
    val integer = s.substring(0, i)
    val frac = s.substring(i + 1).trimEnd('0')
    if (frac.isEmpty()) integer else integer + sep + frac
}
```
Note: Python `s.split(sep, 1)` — the regex guarantees only one sep? `\d+[.,]\d*0+` — only one separator. Good.

`cyrillicFitness`:
```kotlin
fun cyrillicFitness(text: String): Double {
    if (text.isEmpty()) return 0.0
    val alpha = text.filter { it.isLetter() }
    if (alpha.isEmpty()) return 0.0
    val cyr = alpha.count { it.lowercaseChar() in 'а'..'я' || it == 'ё' }
    return cyr.toDouble() / alpha.length
}
```
Python: `c.lower() <= "я"` compares by code point: а(430)..я(44F). Kotlin `in 'а'..'я'` same. And `c in "ёЁ"` → it.lowercaseChar()=='ё' covers Ё. Good.

`latinFitness` similar.

`reattachLeadingPunct`:
```kotlin
private const val PUNCT = ".,!?:;»”’'\"…—–-"
fun reattachLeadingPunct(text: String): String {
    val out = mutableListOf<String>()
    for (tok in text.split(" ")) {
        var i = 0
        while (i < tok.length && tok[i] in PUNCT) i++
        if (i > 0 && i < tok.length && out.isNotEmpty() && out.last().isNotEmpty() &&
            out.last().last() !in PUNCT && out.last().last().isLetterOrDigit()) {
            val last = out.removeAt(out.lastIndex)
            val rest = tok.substring(i)
            out.add(last + tok.substring(0, i))
            if (rest.isNotEmpty()) out.add(rest)
        } else out.add(tok)
    }
    return out.filter { it.isNotEmpty() }.joinToString(" ")
}
```

`isAcceptableCyrillicText`:
```kotlin
private val CYR_ONLY_RE = Regex("^[а-яА-ЯёЁ]+$")
private val LAT_ONLY_RE = Regex("^[a-zA-Z]+$")
fun isAcceptableCyrillicText(text: String): Boolean {
    if (text.isEmpty()) return false
    for (w in text.split(WHITESPACE_RE)) {
        val clean = w.trim(".,!?;:—–-")
        if (clean.isEmpty()) continue
        if (CYR_ONLY_RE.matches(clean)) continue
        if (LAT_ONLY_RE.matches(clean)) continue
        val hasCyr = CYR_RE.containsMatchIn(clean)
        val hasLat = LAT_RE.containsMatchIn(clean)
        if (hasCyr && hasLat) continue
        return false
    }
    return true
}
```
Note Python `text.split()` splits on any whitespace. `CYR_RE` = `[а-яА-ЯёЁ]` is the same one used in filter — good, reuse.

`applyKnownCorrections`:
```kotlin
private val LAT_WORD_RE = Regex("[A-Za-z]+")
fun applyKnownCorrections(text: String): String = LAT_WORD_RE.replace(text) { m ->
    KNOWN_CORRECTIONS[m.value.lowercase()] ?: m.value
}
```

`restoreKnownWords` + `dpSplitOnKnown`:
```kotlin
fun restoreKnownWords(text: String): String {
    if (text.isEmpty()) return text
    val result = mutableListOf<String>()
    for (word in text.split(WHITESPACE_RE).filter { it.isNotEmpty() }) {
        if (word.length < 6 || !CYR_ONLY_RE.matches(word)) { result.add(word); continue }
        val low = word.lowercase()
        if (low in KNOWN_WORDS) { result.add(word); continue }
        val split = dpSplitOnKnown(low, 20)
        if (split != null && split.size > 1 && split.all { it in KNOWN_WORDS }) {
            val restored = mutableListOf<String>()
            var idx = 0
            for (part in split) {
                val slice = word.substring(idx, idx + part.length)
                restored.add(
                    when {
                        slice.isUpperCaseAll() -> part.uppercase()
                        slice.first().isUpperCase() -> part.replaceFirstChar { it.uppercaseChar() }
                        else -> part
                    }
                )
                idx += part.length
            }
            result.add(restored.joinToString(" "))
        } else result.add(word)
    }
    return result.joinToString(" ")
}
```

Careful with `CYR_ONLY_RE.matches(word)` — Python uses `re.match(r"^[а-яА-ЯёЁ]+$", word)` which is a full match due to anchors. Same.

`isUpperCaseAll()` helper: Python `orig_slice.isupper()` → True if all cased chars upper and ≥1 cased char.
```kotlin
private fun String.isUpperCaseAll(): Boolean {
    val cased = filter { it.isLetter() }
    return cased.isNotEmpty() && cased.all { it.isUpperCase() }
}
```

`dpSplitOnKnown`:
```kotlin
fun dpSplitOnKnown(word: String, maxWordLen: Int = 20): List<String>? {
    val n = word.length
    if (n == 0) return emptyList()
    if (n > 200) return null
    val dp = arrayOfNulls<List<String>>(n + 1)
    dp[0] = emptyList()
    for (i in 1..n) {
        for (length in 1..minOf(maxWordLen, i)) {
            val start = i - length
            val candidate = word.substring(start, i)
            val prev = dp[start] ?: continue
            if (candidate in KNOWN_WORDS) {
                val newList = prev + candidate
                val cur = dp[i]
                if (cur == null || newList.size < cur.size) dp[i] = newList
            }
        }
    }
    return dp[n]
}
```

`normalizeLocalCyrillicCaption(text, visualConfusionFix: ((String) -> String)? = null)`:
```kotlin
fun normalizeLocalCyrillicCaption(text: String, fixVisualConfusions: ((String) -> String)? = null): String {
    if (text.isEmpty()) return text
    var t = joinLineHyphens(text)
    t = fixLookalikesPerWord(t)
    t = restoreKnownWords(t)
    if (fixVisualConfusions != null) t = fixVisualConfusions(t)
    return reattachLeadingPunct(t)
}
```

`fullCleanPipeline(text, engineType = "tflite_cyrillic")`:
```kotlin
fun fullCleanPipeline(text: String, engineType: String = "tflite_cyrillic"): String {
    if (text.isEmpty()) return text
    var t = normalizeWhitespace(text)
    t = fixLookalikesPerWord(t)
    t = joinLineHyphens(t)
    if (engineType in setOf("tflite_cyrillic", "cyrillic_onnx", "easyocr")) t = restoreKnownWords(t)
    t = filterGarbageTokens(t)
    t = applyKnownCorrections(t)
    t = normalizeNumbers(t)
    return normalizeWhitespace(t)
}
```
Note: the ramp check only logs in Python — I should preserve it. Python logs a warning. In Kotlin, `android.util.Log` isn't available in unit tests. I'll expose `looksLikeDictionaryRamp` as a public function and let callers decide; the pipeline's ramp check is a log-only side effect. But to stay faithful, I can add an optional `onRamp: (String) -> Unit = {}` param. Hmm, simpler: make fullCleanPipeline take an optional `warn: (String) -> Unit = {}` callback that gets the ramp text. That's clean, testable, and preserves behavior. Let's do that.

File 2: SpeechDecider.kt

```kotlin
package com.screenocr.client.core

import java.util.Locale

object SpeechDecider {
    const val SPEAK = "speak"
    const val REFINE = "refine"
    const val SKIP = "skip"
    ...
}
```

Actually it should be a class with configurable weights (as in Python). Let me make a class `SpeechDecider` with companion holding defaults + regexes, and a `Decision` data class.

```kotlin
data class Decision(val action: String, val score: Double, val reason: String)

class SpeechDecider(
    weights: Map<String, Double> = emptyMap(),
    private val speakAt: Double = 0.55,
    private val refineAt: Double = 0.30,
    private val minScore: Double = 0.0,
) {
    private val w: Map<String, Double> = DEFAULTS + weights
    ...
}
```

minScore is unused in Python's decide (stored but never applied). I should NOT port dead code. Python stores it but never uses it. I'll drop minScore to avoid dead code — but that changes API. Better: drop it and note nothing. Actually, keeping unused constructor param is dead code. Drop it.

features():
```kotlin
fun features(
    text: String,
    hasVoice: Boolean = false,
    voiceText: String = "",
    stability: Int = 0,
    screenPos: Double = 1.0,
    age: Double = 0.0,
    isEcho: Boolean = false,
): Map<String, Double> {
    val t = text.trim()
    val words = WORD_RE.findAll(t).map { it.value }.toList()
    val n = words.size
    val cjkChars = CJK_RE.findAll(t).count()
    val effWords = n + if (cjkChars > 0) cjkChars / 2 else 0
    val letters = t.count { it.isLetter() }
    val digits = t.count { it.isDigit() }
    val marks = t.count { it in ".?!…" }
    val short = words.count { it.length <= 2 }
    val shortRatio = if (n > 0) short.toDouble() / n else 1.0
    val mixed = words.count { w -> w.any { it.isDigit() } }
    val goodWords = if (effWords >= 1) 1.0 else 0.0
    val gibberish = when {
        cjkChars >= 2 -> 1.0
        effWords >= 2 && letters >= 3 && shortRatio <= 0.5 && mixed == 0 &&
            digits <= maxOf(1, letters / 4) -> 1.0
        else -> 0.0
    }
    return linkedMapOf(
        "words" to goodWords,
        "length" to min(1.0, effWords / 6.0),
        "dialog_marks" to if (marks > 0) 1.0 else 0.0,
        "sentence_start" to if (t.firstOrNull()?.isUpperCase() == true || cjkChars > 0) 1.0 else 0.0,
        "screen_pos" to screenPos.coerceIn(0.0, 1.0),
        "stability" to (maxOf(0, stability) / 3.0).coerceAtMost(1.0),
        "freshness" to (1.0 - age / 5.0).coerceAtLeast(0.0),
        "not_gibberish" to gibberish,
        "has_voice" to if (hasVoice) 1.0 else 0.0,
        "voice_text" to if (WORD_RE.findAll(voiceText).count() >= 2 || CJK_RE.findAll(voiceText).count() >= 2) 1.0 else 0.0,
        "overlap_voice" to overlap(voiceText, t),
        "not_echo" to if (isEcho) 0.0 else 1.0,
    )
}
```

Careful: `maxOf(0, stability) / 3.0` → Int / Double = Double. Good. Python `min(1.0, max(0, stability)/3.0)`. `.coerceAtMost(1.0)` on a Double works.

`digits <= maxOf(1, letters / 4)` — letters is Int, `letters / 4` Int division. Good.

decide:
```kotlin
fun decide(text: String, hasVoice: Boolean = false, voiceText: String = "", stability: Int = 0, screenPos: Double = 1.0, age: Double = 0.0, isEcho: Boolean = false): Decision {
    val t = text.trim()
    if (isEcho) return Decision(SKIP, 0.0, "жёсткое правило: это наш собственный голос")
    if (t.isEmpty()) return Decision(SKIP, 0.0, "пустой текст")
    val f = features(t, hasVoice, voiceText, stability, screenPos, age, isEcho)
    var total = 0.0; var weight = 0.0
    val pos = mutableListOf<String>(); val neg = mutableListOf<String>()
    for ((k, v) in f) {
        val wv = w[k] ?: 0.0
        if (wv <= 0) continue
        weight += wv
        total += wv * v
        if (v >= 0.5) pos.add("$k+${fmt(wv * v)}") else neg.add("$k-${fmt(wv * (1.0 - v))}")
    }
    val score = (if (weight != 0.0) total / weight else 0.0).coerceIn(0.0, 1.0)
    val action = when { score >= speakAt -> SPEAK; score >= refineAt -> REFINE; else -> SKIP }
    val reason = "score=${fmt(score)} [порог ${fmt(speakAt)}/${fmt(refineAt)}] за: ${pos.take(4).joinToString(" ").ifEmpty { "-" }} против: ${neg.take(4).joinToString(" ").ifEmpty { "-" }}"
    return Decision(action, score, reason)
}
```
`fmt(x) = String.format(Locale.US, "%.2f", x)`.

Python's `f"{self.speak_at}"` for threshold — `0.55` prints "0.55" and Kotlin fmt gives "0.55". Good. `speak_at: float = 0.55` → "0.55". Good.

overlap:
```kotlin
fun overlap(a: String, b: String): Double {
    val wa = WORD_RE.findAll(a).map { it.value.lowercase() }.toSet()
    val wb = WORD_RE.findAll(b).map { it.value.lowercase() }.toSet()
    if (wa.isEmpty() || wb.isEmpty()) return 0.0
    return wa.intersect(wb).size.toDouble() / maxOf(wa.size, wb.size)
}
```

Note: Python's `min_score` is dropped as dead code. Fine.

File 3: Similarity.kt
```kotlin
object Similarity {
    fun ratio(a0: String, b0: String): Double {
        if (a0.isEmpty() || b0.isEmpty()) return 0.0
        if (a0 == b0) return 1.0
        val maxLen = maxOf(a0.length, b0.length)
        if (abs(a0.length - b0.length) > maxLen * 0.3) return 0.0
        var a = a0; var b = b0
        if (a.length < b.length) { val t = a; a = b; b = t }
        val lb = b.length
        var prev = IntArray(lb + 1)
