def _load_static(path, class_name, func_name):
    """Достаёт метод из класса в обход тяжёлых импортов модуля."""
    import ast
    import textwrap

    src = open(path, encoding="utf-8").read()
    tree = ast.parse(src)
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and node.name == class_name:
            for item in node.body:
                if isinstance(item, ast.FunctionDef) and item.name == func_name:
                    body = textwrap.dedent(ast.get_source_segment(src, item))
                    ns = {"staticmethod": staticmethod, "re": __import__("re")}
                    exec(compile(body, path, "exec"), ns)
                    return ns[func_name]
    raise SystemExit(f"{func_name} not found in {path}")


