package com.screenocr.client.core

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class TextCleanerTest {

    @Test
    fun `mixed alphabet word keeps latin tail and gains a space`() {
        assertEquals(
            "Поискиклонирование yomihon",
            TextCleaner.fixLookalikesPerWord("Поискиклонированиеyomihon"),
        )
    }

    @Test
    fun `cyrillic majority maps latin lookalikes`() {
        assertEquals("Привет саkсаlо", TextCleaner.fixLookalikesPerWord("Привет cаkcаlо"))
    }

    @Test
    fun `pure latin words are preserved`() {
        assertEquals(
            "Мир hello саkсаlо SOS Wi-Fi",
            TextCleaner.fixLookalikesPerWord("Мир hello cаkcаlо SOS Wi-Fi"),
        )
    }

    @Test
    fun `ukrainian letters are folded to russian`() {
        assertEquals("Ыжак испит", TextCleaner.fixLookalikesPerWord("Їжак іспит"))
    }

    @Test
    fun `empty text is returned as is`() {
        assertEquals("", TextCleaner.fixLookalikesPerWord(""))
    }

    @Test
    fun `line hyphenation is joined`() {
        assertEquals(
            "переносится хорошо",
            TextCleaner.joinLineHyphens("пере-\nносится хо-\nрошо"),
        )
    }

    @Test
    fun `garbage tokens are dropped but cyrillic survives`() {
        assertEquals(
            "Привет мир 123 ok",
            TextCleaner.filterGarbageTokens("Привет ★你好 мир 123 ok ★★"),
        )
    }

    @Test
    fun `whitespace and punctuation are normalized`() {
        assertEquals(
            "Привет мир. Как дела?",
            TextCleaner.normalizeWhitespace("  Привет   мир .  Как дела?  "),
        )
    }

    @Test
    fun `ellipsis collapses and space after opening bracket is removed`() {
        assertEquals("(заметка ) и … всё", TextCleaner.normalizeWhitespace("( заметка ) и ... всё"))
    }

    @Test
    fun `trailing zeros are stripped from numbers`() {
        assertEquals(
            "1.5 100 1 12 3,14 2.1 7",
            TextCleaner.normalizeNumbers("1.5000000 100.00000 1.00 12 3,1400 2.10 7"),
        )
    }

    @Test
    fun `known ocr confusions of hotkeys are corrected`() {
        assertEquals(
            "нажми Ctrl и Alt, потом Shift и Del",
            TextCleaner.applyKnownCorrections("нажми curl и alf, потом shlft и dei"),
        )
    }

    @Test
    fun `glued cyrillic words are split by dictionary`() {
        assertEquals("поиск клонирование", TextCleaner.restoreKnownWords("поискклонирование"))
    }

    @Test
    fun `case is restored after split`() {
        assertEquals("ПОИСК КЛОНИРОВАНИЕ", TextCleaner.restoreKnownWords("ПОИСККЛОНИРОВАНИЕ"))
    }

    @Test
    fun `unknown long word is left intact`() {
        assertEquals(
            "неизвестноесловосочетание",
            TextCleaner.restoreKnownWords("неизвестноесловосочетание"),
        )
    }

    @Test
    fun `dictionary ramp is detected`() {
        assertTrue(TextCleaner.looksLikeDictionaryRamp("абвгдеёжзийклмноп"))
        assertFalse(TextCleaner.looksLikeDictionaryRamp("Привет мир как дела"))
    }

    @Test
    fun `leading punctuation is reattached to previous word`() {
        assertEquals("файл, чтобы открыть", TextCleaner.reattachLeadingPunct("файл ,чтобы открыть"))
    }

    @Test
    fun `acceptability check allows cyrillic and latin`() {
        assertTrue(TextCleaner.isAcceptableCyrillicText("Привет мир OK"))
        assertFalse(TextCleaner.isAcceptableCyrillicText("Привет 12abc"))
    }

    @Test
    fun `fitness ratios split by script`() {
        assertEquals(1.0, TextCleaner.cyrillicFitness("Привет мир"), 1e-9)
        assertEquals(0.0, TextCleaner.cyrillicFitness("Hello world"), 1e-9)
        assertEquals(1.0, TextCleaner.latinFitness("Hello world"), 1e-9)
    }

    @Test
    fun `full pipeline cleans a messy ocr line`() {
        assertEquals(
            "Саkсаlо порвдите,что делать? нажми Ctrl 1.5 ★мусор★",
            TextCleaner.fullCleanPipeline("  Cаkcаlо  по-\nрвдите  ,что делать?  нажми curl   1.5000000  ★мусор★  "),
        )
    }

    @Test
    fun `english engine skips cyrillic dictionary split`() {
        assertEquals(
            "Press ctrl and Alt now",
            TextCleaner.fullCleanPipeline("  Press  ctrl   and  alf  now", engineType = "easyocr_en"),
        )
    }

    @Test
    fun `full pipeline reports dictionary ramp`() {
        var reported: String? = null
        val result = TextCleaner.fullCleanPipeline("абвгдеёжзийклмноп") { reported = it }
        assertTrue(reported != null)
        assertEquals(result, reported)
    }
}

package com.screenocr.client.core

import org.junit.Assert.assertEquals
import org.junit.Test

class SpeechDeciderTest {

    private val decider = SpeechDecider()

    @Test
    fun `own voice is never spoken`() {
        val d = decider.decide("Привет как дела", isEcho = true)
        assertEquals(SpeechDecider.SKIP, d.action)
        assertEquals(0.0, d.score, 1e-9)
        assertEquals("жёсткое правило: это наш собственный голос", d.reason)
    }

    @Test
    fun `empty candidate is skipped`() {
        val d = decider.decide("   ")
        assertEquals(SpeechDecider.SKIP, d.action)
        assertEquals(0.0, d.score, 1e-9)
        assertEquals("пустой текст", d.reason)
    }

    @Test
    fun `stable subtitle in the lower screen is spoken`() {
        val d = decider.decide("Привет, как дела?", stability = 3, screenPos = 0.9, age = 0.2)
        assertEquals(SpeechDecider.SPEAK, d.action)
        assertEquals(0.6421, d.score, 1e-4)
        assertEquals(
            "score=0.64 [порог 0.55/0.30] за: words+1.00 length+0.50 dialog_marks+1.20 sentence_start+0.50 " +
                "против: has_voice-2.00 voice_text-1.20 overlap_voice-1.50",
            d.reason,
        )
    }

    @Test
    fun `gibberish is only refined`() {
        val d = decider.decide("OMCK", stability = 3, screenPos = 0.9, age = 0.2)
        assertEquals(SpeechDecider.REFINE, d.action)
        assertEquals(0.4319, d.score, 1e-4)
    }

    @Test
    fun `single letter is not gibberish quality but too short`() {
        val d = decider.decide("X", stability = 3, screenPos = 0.9, age = 0.2)
        assertEquals(SpeechDecider.REFINE, d.action)
        assertEquals(0.4319, d.score, 1e-4)
    }

    @Test
    fun `cjk text is treated as real speech`() {
        val d = decider.decide("你好世界", stability = 3, screenPos = 0.9, age = 0.2)
        assertEquals(SpeechDecider.SPEAK, d.action)
        assertEquals(0.5616, d.score, 1e-4)
    }

    @Test
    fun `text confirmed by voice is spoken`() {
        val d = decider.decide(
            "иди к выходу",
            hasVoice = true,
            voiceText = "иди к выходу",
            stability = 3,
            screenPos = 0.9,
            age = 0.2,
        )
        assertEquals(SpeechDecider.SPEAK, d.action)
        assertEquals(0.8435, d.score, 1e-4)
    }

    @Test
    fun `flickering text drops below speak threshold`() {
        val d = decider.decide("Привет, как дела?", stability = 0, screenPos = 0.9, age = 0.2)
        assertEquals(SpeechDecider.REFINE, d.action)
        assertEquals(0.5348, d.score, 1e-4)
    }

    @Test
    fun `weights are tunable per game`() {
        val tuned = SpeechDecider(weights = mapOf("stability" to 2.0))
        val d = tuned.decide("Привет, как дела?", stability = 0, screenPos = 0.9, age = 0.2)
        assertEquals(SpeechDecider.REFINE, d.action)
        assertEquals(0.5208, d.score, 1e-4)
    }

    @Test
    fun `overlap is a jaccard-like share of the longer side`() {
        assertEquals(0.5, SpeechDecider.overlap("Привет мир", "мир и привет всем"), 1e-9)
        assertEquals(0.0, SpeechDecider.overlap("", "мир"), 1e-9)
    }

    @Test
    fun `features expose every weighted signal`() {
        val keys = decider.features("Привет, как дела?", stability = 3).keys
        assertEquals(SpeechDecider.DEFAULTS.keys, keys)
    }
}

package com.screenocr.client.core

import org.junit.Assert.assertEquals
import org.junit.Test

class SimilarityTest {

    @Test
    fun `identical strings are fully similar`() {
        assertEquals(1.0, Similarity.ratio("Привет", "Привет"), 1e-9)
    }

    @Test
    fun `empty input is not similar`() {
        assertEquals(0.0, Similarity.ratio("", "Привет"), 1e-9)
    }

    @Test
    fun `length mismatch beyond 30 percent is rejected outright`() {
        assertEquals(0.0, Similarity.ratio("abc", "abcdefghijkl"), 1e-9)
    }

    @Test
    fun `trailing punctuation barely changes score`() {
        assertEquals(0.909091, Similarity.ratio("Привет мир", "Привет мир!"), 1e-6)
    }

    @Test
    fun `short common prefix loses to the length guard`() {
        assertEquals(0.0, Similarity.ratio("Привет мир", "Пока"), 1e-9)
    }

    @Test
    fun `no common characters means no similarity`() {
        assertEquals(0.0, Similarity.ratio("abcd", "xyzw"), 1e-9)
    }

    @Test
    fun `is symmetric`() {
        assertEquals(
            Similarity.ratio("Привет мир", "Привет мир!"),
            Similarity.ratio("Привет мир!", "Привет мир"),
            1e-9,
        )
    }
}

package com.screenocr.client.core

import org.junit.Test
import org.junit.Assert.assertEquals

class LanguageDetectorTest {

    @Test
    fun `cyrillic text is russian`() {
        assertEquals(LanguageDetector.RU, LanguageDetector.detect("Привет мир"))
    }

    @Test
    fun `latin text is english`() {
        assertEquals(LanguageDetector.EN, LanguageDetector.detect("Hello world"))
    }

    @Test
    fun `empty text falls back to english`() {
        assertEquals(LanguageDetector.EN, LanguageDetector.detect(""))
    }

    @Test
    fun `digits are not a language`() {
        assertEquals(LanguageDetector.EN, LanguageDetector.detect("12345"))
    }

    @Test
    fun `mixed text follows the thirty percent threshold`() {
        assertEquals(LanguageDetector.RU, LanguageDetector.detect("Привет world"))
        assertEquals(LanguageDetector.RU, LanguageDetector.detect("abc Привет"))
    }
}

