package com.screenocr.client.dict

class JsonFormatException(message: String) : RuntimeException(message)

/**
 * Разбор плоского JSON-объекта вида {"ключ": "значение"}.
 *
 * Словари — это 68 155 пар строк; тянуть ради них JSON-библиотеку в APK
 * незачем, а `org.json` на старте Android парсит такой файл заметно медленнее
 * и недоступен в JVM-тестах (в android.jar он заглушен). Вложенные объекты и
 * массивы не поддерживаются: в словарях их нет, а поддержка была бы кодом без
 * применения.
 */
object FlatJson {

    fun parseObject(text: String): Map<String, String> {
        val reader = Reader(text)
        reader.skipWhitespace()
        reader.expect('{')
        val out = LinkedHashMap<String, String>()
        reader.skipWhitespace()
        if (reader.peek() == '}') {
            reader.read()
            reader.requireEnd()
            return out
        }
        while (true) {
            reader.skipWhitespace()
            val key = reader.readString()
            reader.skipWhitespace()
            reader.expect(':')
            reader.skipWhitespace()
            out[key] = reader.readScalar()
            reader.skipWhitespace()
            when (reader.read()) {
                ',' -> Unit
                '}' -> break
                else -> throw JsonFormatException("ожидался ',' или '}' на позиции ${reader.pos - 1}")
            }
        }
        reader.skipWhitespace()
        reader.requireEnd()
        return out
    }

    private class Reader(private val text: String) {
        var pos = 0

        fun peek(): Char? = if (pos < text.length) text[pos] else null

        fun read(): Char {
            if (pos >= text.length) throw JsonFormatException("неожиданный конец файла")
            return text[pos++]
        }

        fun skipWhitespace() {
            while (pos < text.length && text[pos].isWhitespace()) pos++
        }

        fun expect(c: Char) {
            val actual = read()
            if (actual != c) throw JsonFormatException("ожидался '$c', получен '$actual' на позиции ${pos - 1}")
        }

        fun requireEnd() {
            if (pos != text.length) throw JsonFormatException("лишние данные после объекта на позиции $pos")
        }

        fun readString(): String {
            expect('"')
            val sb = StringBuilder()
            while (true) {
                when (val c = read()) {
                    '"' -> return sb.toString()
                    '\\' -> sb.append(readEscape())
                    else -> sb.append(c)
                }
            }
        }

        private fun readEscape(): Char = when (val c = read()) {
            '"', '\\', '/' -> c
            'b' -> '\b'
            'f' -> ' '
            'n' -> '\n'
            'r' -> '\r'
            't' -> '\t'
            'u' -> {
                val hex = text.substring(pos, pos + 4)
                if (hex.length != 4 || hex.any { it.digitToIntOrNull(16) == null }) {
                    throw JsonFormatException("битый \\u-escape на позиции $pos")
                }
                pos += 4
                hex.toInt(16).toChar()
            }
            else -> throw JsonFormatException("неизвестный escape '\\$c' на позиции ${pos - 1}")
        }

        fun readScalar(): String {
            when (peek()) {
                '"' -> return readString()
                '{', '[' -> throw JsonFormatException("вложенные структуры не поддерживаются на позиции $pos")
                't' -> return literal("true", "true")
                'f' -> return literal("false", "false")
                'n' -> return literal("null", "")
                else -> {
                    val start = pos
                    while (pos < text.length && !text[pos].let { it == ',' || it == '}' || it.isWhitespace() }) pos++
                    val raw = text.substring(start, pos)
                    if (raw.isEmpty()) throw JsonFormatException("пустое значение на позиции $start")
                    return raw
                }
            }
        }

        private fun literal(word: String, value: String): String {
            if (!text.startsWith(word, pos)) throw JsonFormatException("ожидалось '$word' на позиции $pos")
            pos += word.length
            return value
        }
    }
}

package com.screenocr.client.dict

import java.util.Locale

/**
 * Офлайн-перевод EN→RU по словарю, порт `OfflineTranslator` из `offline_dict.py`.
 *
 * Отличия от Python, оба намеренные:
 *
 * - Фразовый проход сделан поиском самого длинного совпадения по хешу вместо
 *   1447 `re.search`/`re.sub` на вызов. Побочный эффект: при перекрывающихся
 *   фразах, когда более длинная начинается правее, выигрывает более ранняя
 *   (в Python — более длинная). На игровых текстах не проявляется.
 * - Переводы с пустым значением отбрасываются. В Python `"of": ""` даёт
 *   двойной пробел в результате.
 */
class OfflineTranslator(
    words: Map<String, String> = DictData.EXTRA_WORDS,
    phrases: Map<String, String> = DictData.PHRASES,
    private val contractions: List<Pair<String, String>> = DictData.CONTRACTIONS,
) {

    private val words: Map<String, String> = words
    private val phrases: Map<String, String> = phrases
    private val maxPhraseLen: Int = phrases.keys.maxOfOrNull { it.length } ?: 0

    fun translate(text: String): String {
        if (text.isEmpty()) return ""
        var t = text.lowercase(Locale.ROOT).trim()
        for ((from, to) in contractions) t = t.replace(from, to)
        phrases[t]?.let { return it }

        val result = mutableListOf<String>()
        var i = 0
        while (i < t.length) {
            val phrase = matchPhrase(t, i)
            if (phrase != null) {
                result.add(phrases.getValue(phrase))
                i += phrase.length
            } else {
                val end = wordEnd(t, i)
                addWord(result, t.substring(i, end))
                i = end
            }
            while (i < t.length && t[i].isWhitespace()) i++
        }
        return result.filter { it.isNotEmpty() }.joinToString(" ")
    }

    fun hasUntranslated(text: String): Boolean {
        val r = translate(text)
        if (r.isEmpty()) return true
        if (r.split(' ').any { it.length > 2 && it.all { c -> c.code < 128 } && it.all { c -> c.isLetter() } }) {
            return true
        }
        val sourceWords = splitWords(text.lowercase(Locale.ROOT)).toSet()
        val resultWords = splitWords(r.lowercase(Locale.ROOT)).toSet()
        if (sourceWords.intersect(resultWords).size > sourceWords.size * 0.5) return true
        return splitWords(r).size < splitWords(text).size * 0.4
    }

    private fun addWord(out: MutableList<String>, token: String) {
        val bare = NON_WORD_RE.replace(token, "")
        if (bare.isEmpty()) return
        if (bare in ARTICLES) return
        out.add(words[bare] ?: bare)
    }

    private fun matchPhrase(text: String, start: Int): String? {
        if (maxPhraseLen == 0) return null
        if (start > 0 && isWordChar(text[start - 1])) return null
        if (!isWordChar(text[start])) return null
        val limit = minOf(maxPhraseLen, text.length - start)
        for (len in limit downTo 1) {
            val end = start + len
            if (end < text.length && isWordChar(text[end])) continue
            val candidate = text.substring(start, end)
            if (candidate in phrases) return candidate
        }
        return null
    }

    private fun wordEnd(text: String, start: Int): Int {
        var end = start
        while (end < text.length && !text[end].isWhitespace()) end++
        return end
    }

    private fun splitWords(text: String): List<String> = text.split(WHITESPACE_RE).filter { it.isNotEmpty() }

    private fun isWordChar(c: Char): Boolean = c == '_' || c.isLetterOrDigit()

    companion object {
        private val ARTICLES = setOf("the", "a", "an")
        private val WHITESPACE_RE = Regex("\\s+")
        private val NON_WORD_RE = Regex("(?U)[^\\w]")
    }
}

package com.screenocr.client.dict

import java.io.File
import java.io.InputStream

class DictSet(val words: Map<String, String>, val phrases: Map<String, String>)

/**
 * Сборка словарей. Порядок загрузки повторяет `OfflineTranslator.__init__`:
 * литералы первыми, JSON дописывается поверх, первое значение выигрывает.
 *
 * `opener` абстрагирует источник: `context.assets.open` на устройстве,
 * `File(...).inputStream()` в тестах.
 */
object DictionaryLoader {

    private const val WORDS_FILE = "en_rus_full.json"
    private const val CITIES_FILE = "cities_dict.json"
    private const val GAMES_FILE = "game_names.json"

    fun load(opener: (String) -> InputStream): DictSet {
        val words = LinkedHashMap(DictData.EXTRA_WORDS)
        putAllMissing(words, WORDS_FILE, opener)
        val phrases = LinkedHashMap(DictData.PHRASES)
        putAllMissing(phrases, CITIES_FILE, opener)
        putAllMissing(phrases, GAMES_FILE, opener)
        return DictSet(words, phrases)
    }

    fun loadFromDir(dir: File): DictSet = load { File(dir, it).inputStream() }

    private fun putAllMissing(target: MutableMap<String, String>, name: String, opener: (String) -> InputStream) {
        val text = opener(name).use { it.readBytes().toString(Charsets.UTF_8) }
        for ((key, value) in FlatJson.parseObject(text)) {
            if (key !in target) target[key] = value
        }
    }
}

