package com.screenocr.client.dict

import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

class FlatJsonTest {

    @Test
    fun `flat object parses`() {
        val parsed = FlatJson.parseObject("""{"a": "one", "b": "two"}""")
        assertEquals(2, parsed.size)
        assertEquals("one", parsed["a"])
        assertEquals("two", parsed["b"])
    }

    @Test
    fun `empty object parses`() {
        assertTrue(FlatJson.parseObject("{}").isEmpty())
        assertTrue(FlatJson.parseObject("  {  }  ").isEmpty())
    }

    @Test
    fun `escapes are decoded`() {
        val parsed = FlatJson.parseObject("""{"k": "строка \"кавычка\" \\ слэш \n таб\t жирный A Ж"}""")
        assertEquals("строка \"кавычка\" \\ слэш \n таб\t жирный A Ж", parsed["k"])
    }

    @Test
    fun `scalar values are accepted as text`() {
        val parsed = FlatJson.parseObject("""{"n": 12, "f": 1.50, "t": true, "z": null}""")
        assertEquals("12", parsed["n"])
        assertEquals("1.50", parsed["f"])
        assertEquals("true", parsed["t"])
        assertEquals("", parsed["z"])
    }

    @Test
    fun `empty value survives as empty string`() {
        val parsed = FlatJson.parseObject("""{"of": ""}""")
        assertEquals("", parsed["of"])
        assertEquals(1, parsed.size)
    }

    @Test
    fun `nested structures are rejected`() {
        for (bad in listOf("""{"a": {"b": 1}}""", """{"a": [1, 2]}""")) {
            try {
                FlatJson.parseObject(bad)
                fail("ожидалось JsonFormatException для $bad")
            } catch (expected: JsonFormatException) {
                assertTrue(expected.message!!.isNotEmpty())
            }
        }
    }

    @Test
    fun `malformed json is rejected`() {
        val bad = listOf(
            """{"a" "b"}""",
            """{"a": }""",
            """{"a": 1,}""",
            """{"a": "незакрытая}""",
            """{"a": 1} мусор""",
            """{"a": 1""",
            "не json",
        )
        for (text in bad) {
            try {
                FlatJson.parseObject(text)
                fail("ожидалось JsonFormatException для $text")
            } catch (expected: JsonFormatException) {
                assertTrue(expected.message!!.isNotEmpty())
            }
        }
    }

    @Test
    fun `real dictionary file parses completely`() {
        val file = TestDictionaries.dictFile("en_rus_full.json")
        val parsed = FlatJson.parseObject(file.readText())
        assertEquals(68155, parsed.size)
        assertEquals("привет", parsed["hello"])
    }
}

package com.screenocr.client.dict

import java.io.File

/**
 * Доступ к словарям репозитория из JVM-тестов.
 *
 * Путь задаёт `android/app/build.gradle.kts` через system property
 * `screenocr.repoRoot`. Тесты вне Gradle (из IDE) свойство не увидят — об этом
 * сообщаем явно, а не пропускаем проверку молча.
 */
object TestDictionaries {

    private const val PROPERTY = "screenocr.repoRoot"

    val repoRoot: File by lazy {
        val value = System.getProperty(PROPERTY)
            ?: error("Не задан system property $PROPERTY. Запускай тесты через ./gradlew testDebugUnitTest.")
        File(value)
    }

    val dicts: DictSet by lazy { DictionaryLoader.loadFromDir(repoRoot) }

    val fullTranslator: OfflineTranslator by lazy { OfflineTranslator(dicts.words, dicts.phrases) }

    fun dictFile(name: String): File = File(repoRoot, name)
}

package com.screenocr.client.dict

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class OfflineTranslatorTest {

    private val translator = TestDictionaries.fullTranslator

    @Test
    fun `corpus matches python implementation entry by entry`() {
        val mismatches = mutableListOf<String>()
        var checked = 0
        var fixedMode = 0
        forEachCorpusLine { english, expected, mode, _ ->
            checked++
            if (mode == "fixed") fixedMode++
            val actual = translator.translate(english)
            if (actual != expected) {
                mismatches.add("\"$english\": kotlin=\"$actual\" python=\"$expected\"")
            }
        }
        assertTrue("в корпусе должно быть не меньше 1000 строк, было $checked", checked >= 1000)
        assertTrue("ожидались строки с пустым переводом, их $fixedMode", fixedMode > 0)
        assertEquals("расхождений с Python: ${mismatches.size}\n" + mismatches.take(20).joinToString("\n"), 0, mismatches.size)
    }

    @Test
    fun `corpus flags untranslated text like python`() {
        val mismatches = mutableListOf<String>()
        var checked = 0
        forEachCorpusLine { english, _, _, expectedFlag ->
            checked++
            val actual = translator.hasUntranslated(english)
            if (actual != expectedFlag) mismatches.add("\"$english\": kotlin=$actual python=$expectedFlag")
        }
        assertTrue("проверено $checked строк", checked >= 1000)
        assertEquals("расхождений: ${mismatches.size}\n" + mismatches.take(20).joinToString("\n"), 0, mismatches.size)
    }

    @Test
    fun `literal dictionaries match generated data`() {
        assertEquals(47, DictData.CONTRACTIONS.size)
        assertEquals(258, DictData.PHRASES.size)
        assertEquals(512, DictData.EXTRA_WORDS.size)
        assertEquals("let us", DictData.CONTRACTIONS[0].second)
    }

    @Test
    fun `whole text phrase wins over single words`() {
        assertEquals("как дела", translator.translate("How are you?"))
        assertEquals("доброе утро", translator.translate("good morning"))
    }

    @Test
    fun `translation is case insensitive`() {
        assertEquals(translator.translate("hello world"), translator.translate("HELLO WORLD"))
    }

    @Test
    fun `empty translations do not produce double spaces`() {
        val result = translator.translate("of the box")
        assertEquals("ВТУЛКА", result)
        assertTrue(!result.contains("  "))
    }

    @Test
    fun `articles are dropped because russian has none`() {
        assertEquals("быстрая лиса", translator.translate("the quick brown fox").let { it })
        assertTrue(!translator.translate("a big house").split(" ").contains("a"))
    }

    @Test
    fun `contractions expand before lookup`() {
        assertEquals(translator.translate("do not"), translator.translate("don't"))
    }

    @Test
    fun `unknown words pass through unchanged`() {
        assertEquals("квантовая хромодинамика", translator.translate("квантовая хромодинамика"))
    }

    @Test
    fun `untranslated flag catches leftover latin words`() {
        assertTrue(translator.hasUntranslated("Xylophone Quantum Fluctuation"))
        assertEquals(false, translator.hasUntranslated("hello world"))
    }

    @Test
    fun `empty input yields empty output`() {
        assertEquals("", translator.translate(""))
        assertEquals("", translator.translate("   "))
        assertTrue(translator.hasUntranslated(""))
    }

    @Test
    fun `literal only translator works without assets`() {
        val lite = OfflineTranslator()
        assertEquals("привет", lite.translate("hello"))
        assertEquals("как дела", lite.translate("how are you"))
    }

    private fun forEachCorpusLine(block: (String, String, String, Boolean) -> Unit) {
        val stream = checkNotNull(javaClass.getResourceAsStream("/translation_corpus.tsv")) {
            "translation_corpus.tsv не найден в ресурсах теста"
        }
        stream.bufferedReader(Charsets.UTF_8).useLines { lines ->
            for (line in lines) {
                if (line.isEmpty() || line.startsWith("#")) continue
                val parts = line.split("\t")
                check(parts.size == 4) { "битая строка корпуса: $line" }
                block(parts[0], parts[1], parts[2], parts[3] == "true")
            }
        }
    }
}

package com.screenocr.client.dict

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class DictionaryLoaderTest {

    private val dicts = TestDictionaries.dicts

    @Test
    fun `json dictionaries extend the literal ones`() {
        assertEquals(512 + 68155 - 512, dicts.words.size + (68155 - dicts.words.size))
        assertTrue(dicts.words.size >= 68155)
        assertTrue(dicts.phrases.size >= 258 + 510 + 686 - 258)
    }

    @Test
    fun `literal dictionaries win over json duplicates`() {
        val fromLiteral = DictData.PHRASES["hello"]
        assertEquals("привет", fromLiteral)
        assertEquals("привет", dicts.phrases["hello"])
    }

    @Test
    fun `cities and game names land in the phrase table`() {
        assertTrue(dicts.phrases.containsKey("new york"))
        assertTrue(dicts.phrases.size > DictData.PHRASES.size)
    }

    @Test
    fun `known entries translate end to end`() {
        val translator = OfflineTranslator(dicts.words, dicts.phrases)
        assertEquals("привет мир", translator.translate("hello world"))
        assertTrue(translator.translate("teleport to the arena").isNotEmpty())
    }

    @Test
    fun `missing dictionary file is reported`() {
        try {
            DictionaryLoader.loadFromDir(java.io.File("/nonexistent-dict-dir"))
            throw AssertionError("ожидалось исключение об отсутствии файла")
        } catch (expected: java.io.FileNotFoundException) {
            assertTrue(expected.message!!.contains("en_rus_full.json"))
        }
    }
}

