package com.screenocr.client

import android.annotation.SuppressLint
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.view.Gravity
import android.view.View.GONE
import android.view.View.VISIBLE
import android.webkit.WebChromeClient
import android.webkit.WebResourceRequest
import android.webkit.WebSettings
import android.webkit.WebView
import android.webkit.WebViewClient
import android.widget.Button
import android.widget.EditText
import android.widget.LinearLayout
import android.widget.ProgressBar
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity

class MainActivity : AppCompatActivity() {

    private lateinit var serverView: WebView
    private lateinit var connectLayout: LinearLayout
    private lateinit var urlInput: EditText
    private lateinit var loading: ProgressBar
    private lateinit var prefs: android.content.SharedPreferences

    companion object {
        private const val PREF_URL = "server_url"
        private const val DEFAULT_URL = "https://screenocr-pro-server.trycloudflare.com"
    }

    @SuppressLint("SetJavaScriptEnabled")
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        prefs = getSharedPreferences("screenocr", MODE_PRIVATE)

        serverView = WebView(this)
        serverView.layoutParams = LinearLayout.LayoutParams(
            LinearLayout.LayoutParams.MATCH_PARENT,
            LinearLayout.LayoutParams.MATCH_PARENT
        )
        serverView.settings.apply {
            javaScriptEnabled = true
            domStorageEnabled = true
            mediaPlaybackRequiresUserGesture = false
            cacheMode = WebSettings.LOAD_DEFAULT
            useWideViewPort = true
            loadWithOverviewMode = true
            mixedContentMode = WebSettings.MIXED_CONTENT_ALWAYS_ALLOW
        }
        serverView.webChromeClient = object : WebChromeClient() {
            override fun onProgressChanged(view: WebView?, progress: Int) {
                if (progress < 100) {
                    if (loading.visibility != VISIBLE) loading.visibility = VISIBLE
                } else {
                    loading.visibility = GONE
                }
            }
        }
        serverView.webViewClient = object : WebViewClient() {
            override fun shouldOverrideUrlLoading(view: WebView?, request: WebResourceRequest?): Boolean {
                val url = request?.url?.toString() ?: return false
                if (url.startsWith("http://") || url.startsWith("https://")) {
                    // внешние ссылки (напр. Google translate) — тоже внутри WebView
                    view?.loadUrl(url)
                    return true
                }
                return false
            }
        }

        connectLayout = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.CENTER_HORIZONTAL
            setPadding(50, 120, 50, 50)
            setBackgroundColor(0xFF0D1117.toInt())
        }
        val title = TextView(this).apply {
            text = "🔍 ScreenOCR Client"
            textSize = 24f
            setTextColor(0xFF7B68EE.toInt())
            gravity = Gravity.CENTER
        }
        val hintText = TextView(this).apply {
            text = "Вставь URL проф-сервера из workflow GitHub\nи нажми «Подключиться»"
            textSize = 14f
            setTextColor(0xFF8B949E.toInt())
            gravity = Gravity.CENTER
        }
        urlInput = EditText(this).apply {
            setText(prefs.getString(PREF_URL, DEFAULT_URL))
            textSize = 14f
            hint = "https://….trycloudflare.com"
            setBackgroundColor(0xFF161B22.toInt())
            setTextColor(0xFFE6EDF3.toInt())
        }
        val connectBtn = Button(this).apply {
            text = "🔌 Подключиться"
            setOnClickListener { openUrl(urlInput.text.toString().trim()) }
        }
        val clearBtn = Button(this).apply {
            text = "Ввести другой адрес"
            setOnClickListener {
                prefs.edit().remove(PREF_URL).apply()
                serverView.visibility = GONE
                connectLayout.visibility = VISIBLE
                urlInput.setText(DEFAULT_URL)
            }
        }
        connectBtn.setOnClickListener { openUrl(urlInput.text.toString().trim()) }

        connectLayout.addView(title, lp())
        connectLayout.addView(hintText, lp(marginTop = 12))
        connectLayout.addView(urlInput, lp(marginTop = 24))
        connectLayout.addView(connectBtn, lp(marginTop = 18))
        connectLayout.addView(clearBtn, lp(marginTop = 10))

        loading = ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal).apply {
            max = 100
        }

        val root = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        root.addView(serverView)
        root.addView(loading, lp())
        root.addView(connectLayout)

        serverView.visibility = GONE
        loading.visibility = GONE
        setContentView(root)

        val saved = prefs.getString(PREF_URL, "")
        if (saved?.isNotBlank() == true && (saved.startsWith("http://") || saved.startsWith("https://"))) {
            openUrl(saved)
        }
    }

    private fun lp(marginTop: Int = 0) = LinearLayout.LayoutParams(
        LinearLayout.LayoutParams.MATCH_PARENT,
        LinearLayout.LayoutParams.WRAP_CONTENT
    ).apply { topMargin = marginTop }

    private fun openUrl(url: String) {
        if (url.isBlank()) return
        val fixed = if (!url.startsWith("http")) "http://$url" else url
        prefs.edit().putString(PREF_URL, fixed).apply()
        connectLayout.visibility = GONE
        serverView.visibility = VISIBLE
        serverView.loadUrl(fixed)
    }

    override fun onBackPressed() {
        if (serverView.visibility == VISIBLE && serverView.canGoBack()) {
            serverView.goBack()
        } else {
            super.onBackPressed()
        }
    }

    override fun onDestroy() {
        serverView.destroy()
        super.onDestroy()
    }
}

parts.text:
Theme uses `Theme.MaterialComponents.DayNight.NoActionBar` (from the material library). With Compose, I can keep that theme and apply a Compose `MaterialTheme` inside — that works since the activity theme just needs to be a non-AppCompat theme; `ComponentActivity` works with any theme. Keeping `Theme.MaterialComponents` requires the material dependency (already present).

Now let me write the build.gradle.kts changes.

Compose compiler 1.5.10 + BOM 2024.02.02. Note: with compose BOM 2024.02.02, material3 is 1.2.0. Requires compileSdk 34 — we have it. Good.

Let me write the files.

build.gradle.kts:
```kotlin
android {
    ...
    buildFeatures { compose = true }
    composeOptions { kotlinCompilerExtensionVersion = "1.5.10" }
}
dependencies {
    implementation(platform("androidx.compose:compose-bom:2024.02.02"))
    implementation("androidx.compose.ui:ui")
    implementation("androidx.compose.ui:ui-graphics")
    implementation("androidx.compose.material3:material3")
    implementation("androidx.activity:activity-compose:1.8.2")
    debugImplementation("androidx.compose.ui:ui-tooling")
    ...
}
```

Now the code.

**core/TranslationPipeline.kt**:
```kotlin
package com.screenocr.client.core

import com.screenocr.client.dict.OfflineTranslator

data class TranslationResult(
    val input: String,
    val cleaned: String,
    val translation: String,
    val language: String,
    val needsBetterTranslation: Boolean,
)

class TranslationPipeline(
    private val cleaner: TextCleaner = ...,
    private val translator: OfflineTranslator,
)
```
TextCleaner is an object, so no instance needed. Let me make it a class with a `textCleaner` lambda defaulting to TextCleaner::fullCleanPipeline? Simpler: just call the object directly and take the translator as a constructor param.

```kotlin
class TranslationPipeline(private val translator: OfflineTranslator) {
    fun process(raw: String): TranslationResult {
        val cleaned = TextCleaner.fullCleanPipeline(raw)
        val translation = translator.translate(cleaned)
        return TranslationResult(
            input = raw,
            cleaned = cleaned,
            translation = translation,
            language = LanguageDetector.detect(translation),
            needsBetterTranslation = translator.hasUntranslated(cleaned),
        )
    }
}
```
Wait: LanguageDetector.detect on the *translation* (Russian) → "ru". On English input that failed to translate → "en". Hmm, what's the right language to speak? The TTS should speak in the language of the text it will pronounce — which is the translation. So detect on `translation`. But if translation is empty → falls back to "en". Let me detect on the translation, falling back to the cleaned input if the translation is empty. Actually simpler and more sensible: detect on `translation.ifEmpty { cleaned }`. Let me keep that.

Also: the pipeline should only translate if the input is English. If the OCR text is already Russian (a Russian game), we should speak it as-is, not "translate" it. Python's `live_scanner` checks `_detect_text_language` and picks the TTS voice. So: if the detected language of `cleaned` is "ru", skip translation. Let me model that:

```kotlin
fun process(raw: String): TranslationResult {
    val cleaned = TextCleaner.fullCleanPipeline(raw)
    val sourceLanguage = LanguageDetector.detect(cleaned)
    val translation = if (sourceLanguage == LanguageDetector.RU) cleaned else translator.translate(cleaned)
    ...
}
```
That's the sensible end-to-end behavior and matches how the Python app uses it. Good.

**tts/SpeechEngine.kt**:
```kotlin
package com.screenocr.client.tts

interface SpeechEngine {
    val isReady: Boolean
    fun speak(text: String, language: String)
    fun stop()
    fun shutdown()
}

interface SpeechListener {
    fun onReady(available: Boolean)
    fun onStarted()
    fun onFinished()
    fun onFailed(message: String)
}
```

**tts/TtsVoiceSelector.kt** (pure, tested):
```kotlin
object TtsVoiceSelector {
    fun select(voices: List<VoiceCandidate>, language: String): VoiceCandidate?
}
data class VoiceCandidate(val id: String, val locale: String, val name: String?)
```
Selection rules:
- Prefer a voice whose locale matches the language exactly ("ru" → "ru-RU" or "ru_*"), else the base language match, else null.
- Among matches, prefer a "network" voice? No — prefer local (offline) voices to avoid network latency. But quality... For a first slice, prefer any; prefer non-network (local) when available since it works offline. Let me implement: filter by language; among them prefer local (isNetworkConnectionRequired == false), then prefer higher quality. Let me keep it simple and testable:
  ```kotlin
  fun select(voices, language): VoiceCandidate? =
      voices.filter { it.language == language }
            .minByOrNull { rank }   // rank: local first, then longer locale tag (more specific)
  ```
  where `VoiceCandidate(id, locale, name, isNetworkRequired)`.

Also a `LocaleTags` helper: `Locale("ru").toLanguageTag()`.

Let me define:
```kotlin
data class TtsVoice(val id: String, val locale: String, val name: String, val requiresNetwork: Boolean)

object TtsVoiceSelector {
    fun select(voices: List<TtsVoice>, language: String): TtsVoice? {
        val target = language.lowercase(Locale.ROOT)
        return voices
            .filter { it.locale.substringBefore('-').lowercase(Locale.ROOT) == target }
            .minWithOrNull(compareBy({ it.requiresNetwork }, { -it.locale.length }, { it.name }))
    }
    fun voicesOf(tts: TextToSpeech): List<TtsVoice>  // Android-specific, in AndroidTtsEngine instead
}
```
`minWithOrNull` with a Comparator<in TtsVoice> — compareBy with mixed types. Let me write it explicitly:
```kotlin
.sortedWith(compareBy<TtsVoice> { it.requiresNetwork }.thenByDescending { it.locale.length }.thenBy { it.name })
.firstOrNull()
```

**tts/SpeechText.kt** (pure, tested): prepares text for speaking.
```kotlin
object SpeechText {
    fun prepare(text: String): String {
        val collapsed = text.replace(Regex("\\s+"), " ").trim()
        if (collapsed.isEmpty()) return ""
        return if (collapsed.length > MAX_CHARS) ... 
    }
}
```
Should I chunk long text? Android TTS has an utterance limit (~4000 chars for the old queue, but modern engines handle long text). A simple guard: truncate at a sentence boundary under 4000 chars. Let me implement a reasonable chunker: split into sentences and emit utterances <= 500 chars, joined with QUEUE_ADD. That maps well to `speak(text, language, flush)`.

Actually let me keep the engine API simple: `speak(text, language)` and let the engine chunk internally. `SpeechText.chunks(text): List<String>` is pure and testable, and AndroidTtsEngine enqueues them.

Rules for chunks:
- collapse whitespace
- if empty → emptyList
- accumulate sentences (split after . ! ? … followed by space or end) up to MAX (e.g. 400 chars); if a single sentence exceeds MAX, hard-split on spaces.

That's testable and useful. Let me write it.

**tts/AndroidTtsEngine.kt**:
```kotlin
class AndroidTtsEngine(
    private val listener: SpeechListener,
    private val onInit: (TextToSpeech) -> Unit,
) : SpeechEngine {
    private var tts: TextToSpeech? = null
    private var ready = false
    override val isReady get() = ready
    ...
}
```
Hmm, passing the TTS in via a lambda makes it testable-ish but AndroidTtsEngine itself needs a Context. Let me make it take a Context and construct TextToSpeech internally, and keep all testable logic in the pure objects.

```kotlin
class AndroidTtsEngine(context: Context, private val listener: SpeechListener) : SpeechEngine {
    private val appContext = context.applicationContext
    private var tts: TextToSpeech? = null
    @Volatile private var ready = false
    private val initLock = CountDownLatch(1)  // hmm, blocking
```
Blocking on init is bad. Let me use the listener callback: `onReady(available)` fires when init completes; the UI enables the button.

speak():
```kotlin
override fun speak(text: String, language: String) {
    val engine = tts ?: run { listener.onFailed("TTS не инициализирован"); return }
    if (!ready) { listener.onFailed("Голос ещё не готов"); return }
    val chunks = SpeechText.chunks(text)
    if (chunks.isEmpty()) { listener.onFailed("Нет текста для озвучки"); return }
    val voice = TtsVoiceSelector.select(voices(), language)
    if (voice != null) { engine.voice = engine.getVoice(voice.id) }
    else { val l = Locale.forLanguageTag(localeTagFor(language)); engine.language = l }
    chunks.forEachIndexed { i, chunk -> engine.speak(chunk, QUEUE_FLUSH if i==0 else QUEUE_ADD, null, "screenocr-$i") }
}
```
Note: `engine.voice` requires API 21+. minSdk 23. Fine. `Voice` requires API 21.

UtteranceProgressListener for started/finished/error.

**MainActivity** (Compose):
```kotlin
class MainActivity : ComponentActivity() {
    private lateinit var engine: SpeechEngine
    override fun onCreate(...) {
        super.onCreate(savedInstanceState)
        engine = AndroidTtsEngine(this, TtsUiBridge)   // hmm, needs to update Compose state
        setContent { TranslatorApp(engine) }
    }
    override fun onDestroy() { engine.shutdown(); super.onDestroy() }
}
```
The listener needs to push state into Compose. Cleanest: a `TranslatorViewModel`-ish state holder class `TranslatorState` holding `MutableStateFlow`s, created in the Activity, passed to both the engine listener and the composable. Let me write:

```kotlin
class TranslatorViewModel(application: Application) : AndroidViewModel(application) {
    val state = MutableStateFlow(UiState())
    ...
}
```
That needs `androidx.lifecycle:lifecycle-viewmodel-compose` (or just use AndroidViewModel from lifecycle-viewmodel-ktx, which comes with activity-ktx? `androidx.activity:activity-ktx` doesn't include lifecycle-viewmodel. `androidx.lifecycle:lifecycle-viewmodel-ktx` is a separate dep but tiny and standard.

