package com.screenocr.client.tts

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

class TtsVoiceSelectorTest {

    private val voices = listOf(
        TtsVoice("ru-net", "ru-RU", "Russian (network)", requiresNetwork = true),
        TtsVoice("ru-local", "ru-RU", "Russian local", requiresNetwork = false),
        TtsVoice("ru-old", "ru", "Russian generic", requiresNetwork = false),
        TtsVoice("en-us", "en-US", "English US", requiresNetwork = false),
        TtsVoice("en-gb", "en-GB", "English GB", requiresNetwork = false),
        TtsVoice("de-de", "de-DE", "German", requiresNetwork = false),
    )

    @Test
    fun `local voice wins over network voice`() {
        assertEquals("ru-local", TtsVoiceSelector.select(voices, "ru")?.id)
    }

    @Test
    fun `regional tag wins over bare language`() {
        assertEquals("ru-local", TtsVoiceSelector.select(listOf(TtsVoice("ru-old", "ru", "generic", false), TtsVoice("ru-local", "ru-RU", "regional", false)), "ru")?.id)
    }

    @Test
    fun `english selection is independent of russian voices`() {
        assertEquals("en-us", TtsVoiceSelector.select(voices, "en")?.id)
    }

    @Test
    fun `missing language yields null so the engine can fall back`() {
        assertNull(TtsVoiceSelector.select(voices, "fr"))
    }

    @Test
    fun `selection is case insensitive`() {
        assertEquals("ru-local", TtsVoiceSelector.select(voices, "RU")?.id)
    }

    @Test
    fun `network only language still resolves`() {
        val onlyNetwork = listOf(TtsVoice("ru-net", "ru-RU", "Russian net", requiresNetwork = true))
        assertEquals("ru-net", TtsVoiceSelector.select(onlyNetwork, "ru")?.id)
    }

    @Test
    fun `locale tags map to engine locales`() {
        assertEquals("ru-RU", TtsVoiceSelector.localeTagFor("ru"))
        assertEquals("en-US", TtsVoiceSelector.localeTagFor("en"))
    }
}

package com.screenocr.client.tts

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class SpeechTextTest {

    @Test
    fun `empty text produces no chunks`() {
        assertTrue(SpeechText.chunks("").isEmpty())
        assertTrue(SpeechText.chunks("   \n\t ").isEmpty())
    }

    @Test
    fun `short text stays in one chunk`() {
        assertEquals(listOf("Привет, как дела?"), SpeechText.chunks("  Привет,   как дела?  "))
    }

    @Test
    fun `newline and tabs collapse into single spaces`() {
        assertEquals(listOf("раз два три"), SpeechText.chunks("раз\nдва\t\tтри"))
    }

    @Test
    fun `long text splits on sentence boundaries`() {
        val sentence = "Это предложение ровно такой длины, чтобы проверить разбиение. "
        val text = sentence.repeat(4)
        val chunks = SpeechText.chunks(text)
        assertTrue("ожидалось больше одного куска, получено ${chunks.size}", chunks.size > 1)
        assertTrue(chunks.all { it.length <= SpeechText.MAX_CHUNK })
        assertTrue(chunks.none { it.isEmpty() })
    }

    @Test
    fun `a single oversized sentence splits on words`() {
        val long = (1..120).joinToString(" ") { "слово$it" }
        val chunks = SpeechText.chunks(long)
        assertTrue(chunks.size > 1)
        assertTrue(chunks.all { it.length <= SpeechText.MAX_CHUNK })
        assertEquals(long.split(" ").joinToString(" "), chunks.joinToString(" "))
    }

    @Test
    fun `no words are lost or duplicated`() {
        val text = "Раз. Два! Три? Четыре… Пять. " + "Шесть ".repeat(80)
        val restored = SpeechText.chunks(text).joinToString(" ")
        assertEquals(text.replace(Regex("\\s+"), " ").trim(), restored)
    }
}

package com.screenocr.client.core

import com.screenocr.client.dict.DictionaryLoader
import com.screenocr.client.dict.OfflineTranslator
import com.screenocr.client.dict.TestDictionaries
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class TranslationPipelineTest {

    private val pipeline = TranslationPipeline(
        OfflineTranslator(TestDictionaries.dicts.words, TestDictionaries.dicts.phrases),
    )

    @Test
    fun `english input is translated`() {
        val result = pipeline.process("Hello world")
        assertEquals("en", result.sourceLanguage)
        assertEquals("привет мир", result.spoken)
        assertEquals("ru", result.language)
        assertFalse(result.needsBetterTranslation)
    }

    @Test
    fun `russian input is spoken as is`() {
        val result = pipeline.process("Привет мир")
        assertEquals("ru", result.sourceLanguage)
        assertEquals("Привет мир", result.spoken)
        assertEquals("ru", result.language)
        assertFalse(result.needsBetterTranslation)
    }

    @Test
    fun `cleaning runs before translation`() {
        val result = pipeline.process("  Cаkcаlо  нажми curl  ")
        assertTrue(result.cleaned.contains("Ctrl"))
        assertTrue(result.spoken.isNotEmpty())
    }

    @Test
    fun `uncovered latin text raises the warning flag`() {
        val result = pipeline.process("Blorp Snarfle")
        assertEquals("en", result.sourceLanguage)
        assertTrue(result.needsBetterTranslation)
    }

    @Test
    fun `empty input yields empty speech`() {
        val result = pipeline.process("   ")
        assertEquals("", result.spoken)
    }

    @Test
    fun `input is preserved for display`() {
        val raw = "  Hello   world  "
        assertEquals(raw, pipeline.process(raw).input)
    }
}

