@staticmethod
def _split_sentences(text: str) -> list:
    """Разбивает текст на предложения."""
    if not text or not text.strip():
        return []
    parts = re.split(r'(?<=[.!?])\s+|\n{2,}', text.strip())
    result = []
    for p in parts:
        p = p.strip()
        if not p:
            continue
        if len(p) > 80:
            sub = re.split(r'(?<=,)\s+', p)
            result.extend(s.strip() for s in sub if s.strip())
        else:
            result.append(p)
    return result

