def _clean_ocr(self, text):
    import re
    lines = text.split('\n')
    cleaned = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        if re.search(r'[а-яА-ЯёЁ]', line):
            continue
        line = re.sub(r'^\d{1,2}:\d{2}(:\d{2})?[\.,]?\d*\s*', '', line)
        if not re.search(r'[a-zA-Z]{2,}', line):
            continue
        cleaned.append(line.strip())
    return '\n'.join(cleaned)

